input.command:
cat > "$TMP_DIR/gen.js" << 'EOF'
const React = require("react");
const { renderToStaticMarkup } = require("react-dom/server");
const icons = require("outline-icons");
const fs = require("fs");

const names = Object.keys(icons).filter((n) => n !== "Icon").sort();
const cards = names.map((n) => {
  let svg = "";
  try {
    svg = renderToStaticMarkup(React.createElement(icons[n], { size: 28 }));
  } catch (e) {
    svg = "<span>?</span>";
  }
  return `<button class="card" data-name="${n.toLowerCase()}" onclick="copy('${n}')"><span class="ico">${svg}</span><span class="nm">${n}</span></button>`;
}).join("\n");

const html = `<!doctype html>
<html><head><meta charset="utf-8"><title>outline-icons</title>
<style>
:root{--bg:#fff;--fg:#111;--muted:#666;--line:#e5e5e5;--hover:#f4f4f5}
@media (prefers-color-scheme:dark){:root{--bg:#18181b;--fg:#f4f4f5;--muted:#a1a1aa;--line:#2f2f35;--hover:#26262b}}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--fg);font:14px/1.4 -apple-system,Segoe UI,sans-serif;padding:24px}
header{position:sticky;top:0;background:var(--bg);padding-bottom:12px}
h1{font-size:18px;margin:0 0 12px}
#q{width:100%;max-width:420px;padding:8px 10px;border:1px solid var(--line);border-radius:6px;background:transparent;color:var(--fg);font-size:14px}
#count{color:var(--muted);margin-left:8px;font-size:12px}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:4px;margin-top:12px}
.card{display:flex;align-items:center;gap:8px;padding:8px;border:none;background:transparent;color:var(--fg);border-radius:6px;cursor:pointer;text-align:left;font:inherit;overflow:hidden}
.card:hover{background:var(--hover)}
.ico{flex:0 0 28px;display:flex}
.nm{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
</style></head>
<body>
<header><h1>outline-icons <span id="count">${names.length} icons — click to copy name</span></h1>
<input id="q" placeholder="Search…" autofocus></header>
<div class="grid" id="grid">
${cards}
</div>
<script>
const q=document.getElementById('q'),cards=[...document.querySelectorAll('.card')],c=document.getElementById('count');
q.addEventListener('input',()=>{const v=q.value.toLowerCase();let n=0;cards.forEach(el=>{const m=el.dataset.name.includes(v);el.style.display=m?'':'none';if(m)n++});c.textContent=n+' icons — click to copy name'});
function copy(n){navigator.clipboard&&navigator.clipboard.writeText(n);c.textContent='Copied '+n}
</script>
</body></html>`;
fs.writeFileSync(process.argv[2], html);
console.log("wrote", names.length, "icons");
EOF
